window.docContents[221].resolve({"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Type-Classes-and-Overloading--Head-and-Tail":{"contents":"The head function returns the first element (the \"head\") of\nthe list, while tail returns everything but the first element (the\n\"tail\").  Since the empty list has no first element, we pass\na default value to be returned in that case.\n\ndef head (default : Nat) (l : NatList) : Nat :=\n  match l with\n  | [] => default\n  | h :: _ => h\ndef head (default : Nat) (l : NatList) : Nat :=\n  match l with\n  | [] => default\n  | h :: _ => h\ndef head (default : Nat) (l : NatList) : Nat :=\n  match l with\n  | [] => default\n  | h :: _ => h\n\n\nBasic theorems about how head behaves:\n\ntheorem head_cons {h x : Nat} {t : NatList} : (h :: t).head x = h := by rfl\n\ntheorem head_nil {x : Nat} : [].head x = x := by rfl\n\ndef tail (l : NatList) : NatList :=\n  match l with\n  | [] => []\n  | _ :: t => t\ntheorem head_cons {h x : Nat} {t : NatList} : (h :: t).head x = h := by rfl\n\ntheorem head_nil {x : Nat} : [].head x = x := by rfl\n\ndef tail (l : NatList) : NatList :=\n  match l with\n  | [] => []\n  | _ :: t => t\ntheorem head_cons {h x : Nat} {t : NatList} : (h :: t).head x = h := by rfl\n\ntheorem head_nil {x : Nat} : [].head x = x := by rfl\n\ndef tail (l : NatList) : NatList :=\n  match l with\n  | [] => []\n  | _ :: t => t\n\n\nBasic theorems about how tail behaves:\n\ntheorem tail_cons {h : Nat} {t : NatList} : (h :: t).tail = t := by rfl\n\ntheorem tail_nil : [].tail = [] := by rfl\n\nexample : head 0 [1, 2, 3] = 1 := by rw [head_cons]\nexample : head 0 [] = 0 := by rw [head_nil]\nexample : [1, 2, 3].tail = [2, 3] := by rw [tail_cons]\ntheorem tail_cons {h : Nat} {t : NatList} : (h :: t).tail = t := by rfl\n\ntheorem tail_nil : [].tail = [] := by rfl\n\nexample : head 0 [1, 2, 3] = 1 := by rw [head_cons]\nexample : head 0 [] = 0 := by rw [head_nil]\nexample : [1, 2, 3].tail = [2, 3] := by rw [tail_cons]\ntheorem tail_cons {h : Nat} {t : NatList} : (h :: t).tail = t := by rfl\n\ntheorem tail_nil : [].tail = [] := by rfl\n\nexample : head 0 [1, 2, 3] = 1 := by rw [head_cons]\nexample : head 0 [] = 0 := by rw [head_nil]\nexample : [1, 2, 3].tail = [2, 3] := by rw [tail_cons]\n\n\nWhat does the following function do?def foo (n : Nat) : NatList :=\n  match n with\n  | 0 => []\n  | n' + 1 => (n' + 1) :: foo n'\ndef foo (n : Nat) : NatList :=\n  match n with\n  | 0 => []\n  | n' + 1 => (n' + 1) :: foo n'\ndef foo (n : Nat) : NatList :=\n  match n with\n  | 0 => []\n  | n' + 1 => (n' + 1) :: foo n'\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Lists of Numbers\u0009Type Classes and Overloading","header":"5.2.3.1. Head and Tail","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Type-Classes-and-Overloading--Head-and-Tail"}});